-- GENERATED by scripts/gen_places_seed.py — do not hand-edit.
-- Regenerate against a newer snapshot and diff; zero diff means the places have not moved.
--
-- ⭐ PLACES ARE ENTITIES WITH PAGES, NOT STRINGS ON AN ITEM (DECISIONS.md, 2026-09-13), and
-- they are a HIERARCHY: region -> map -> place -> place. Some instances contain instances
-- (House of Crom, Warmonk Monastery) and some hang straight off a region with no map at all
-- (Skull Gate Pass, Kuthchemes) — which is why parent_place_id exists and map_id is NULL-able.
--
-- ⭐ AN UNCHAINED DUNGEON IS ITS OWN ROW, not a flag on its twin: seven places exist in both
-- forms and ZERO items are shared between any pair (Pierre, 2026-09-13). The boolean is kept
-- as a cheap filter — 'show me every Unchained dungeon' — but the PLACE is the truth.
--
-- ⚠️ EVERY ROW CARRIES ITS PROVENANCE: source_note says which of the two sources it came
-- from, confidence follows reference/sourcing-standards.md § 3, and open_question holds what
-- is still unknown. `WHERE open_question IS NOT NULL` is the list of things to ask Pierre.
-- An empty field is a feature; a confident guess is a bug that reaches a raid.
--
-- ⚠️ EVERY SEED IS `ON CONFLICT DO NOTHING` (AOC-005's convention, pinned by
-- TestEverySeedInsertIsIdempotent).

-- +goose Up

-- The confidence vocabulary of reference/sourcing-standards.md § 3, as rows rather than an
-- ENUM, because a fifth value must be an INSERT and not a migration of every content table.
CREATE TABLE confidence_levels (
    id         serial PRIMARY KEY,
    slug       varchar(64) NOT NULL UNIQUE,
    name       varchar(64) NOT NULL UNIQUE,
    sort_order integer     NOT NULL
);

-- 8 regions. Pierre confirmed the list is COMPLETE (Tier A, 2026-09-13); the
-- armory knows only 6 of them and would silently lose Tortage and Kush.
CREATE TABLE regions (
    id            serial PRIMARY KEY,
    slug          varchar(64)  NOT NULL UNIQUE,
    name          varchar(64)  NOT NULL UNIQUE,
    sort_order    integer      NOT NULL,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);

-- 26 maps — the playfield an instance's entrance sits in.
-- region_id is NULL-able on purpose: a map the armory knows and Pierre's tree does not may
-- arrive before anyone can say which region it belongs to.
CREATE TABLE maps (
    id            serial PRIMARY KEY,
    region_id     integer      NULL REFERENCES regions(id),
    slug          varchar(64)  NOT NULL UNIQUE,
    name          varchar(96)  NOT NULL UNIQUE,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);

-- 86 places: the dungeons, raids and arenas you zone into.
--
-- ⚠️ map_id is NULL-able and region_id is NOT — not the other way round. Skull Gate Pass and
-- Kuthchemes are entered from the Raid Finder and have no map between them and their region,
-- so a NOT NULL map_id would have no value to put there but a made-up one.
--
-- ⚠️ region_id is carried even when map_id is set. It is redundant by design: 'every place in
-- Stygia' is then one join rather than a COALESCE over two paths, and the generator is the
-- only writer, so the two cannot drift. Pinned by TestEveryPlacesRegionMatchesItsMap.
--
-- armory_instance / armory_dungeon are the source spellings this place was filed under, kept
-- so AOC-011 can join 6,641 item source rows onto these rows without re-deriving the mapping
-- from scratch. They are the alias record too: 'The Pit Master's Arena' is how the armory
-- spells Fight Club Arena.
CREATE TABLE places (
    id              serial PRIMARY KEY,
    region_id       integer      NOT NULL REFERENCES regions(id),
    map_id          integer      NULL REFERENCES maps(id),
    parent_place_id integer      NULL REFERENCES places(id),
    slug            varchar(96)  NOT NULL UNIQUE,
    name            varchar(96)  NOT NULL UNIQUE,
    unchained       boolean      NOT NULL DEFAULT false,
    armory_instance varchar(96)  NULL,
    armory_dungeon  varchar(96)  NULL,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);

-- The importer's join key. Partial, because the places Pierre knows and the armory never
-- filed an item under share (NULL, NULL) and must not collide with each other.
CREATE UNIQUE INDEX places_armory_key ON places (armory_instance, armory_dungeon)
    NULLS NOT DISTINCT
    WHERE armory_instance IS NOT NULL OR armory_dungeon IS NOT NULL;
CREATE INDEX places_region_id_idx ON places (region_id);
CREATE INDEX places_map_id_idx ON places (map_id);
CREATE INDEX places_parent_place_id_idx ON places (parent_place_id);

-- 44 bosses. place_id is NULL-able: five of them were confirmed by Pierre as
-- bosses the armory had filed as places, and they keep their map and region but have no
-- instance recorded. EP-03 hangs the mechanics — the actual product — off these rows.
CREATE TABLE bosses (
    id            serial PRIMARY KEY,
    place_id      integer      NULL REFERENCES places(id),
    map_id        integer      NULL REFERENCES maps(id),
    region_id     integer      NULL REFERENCES regions(id),
    slug          varchar(96)  NOT NULL UNIQUE,
    name          varchar(96)  NOT NULL UNIQUE,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);
CREATE INDEX bosses_place_id_idx ON bosses (place_id);

-- 51 quests — and `name` is NULL for every one of them, on purpose.
-- The armory's quest column holds the quest GIVER ('Muriela'), a hub ('Conall's Valley') or
-- a bucket ('Destiny quests') as often as a quest title, so armory_label records exactly what
-- the source said and `name` waits for someone who knows. An empty field is a feature.
CREATE TABLE quests (
    id            serial PRIMARY KEY,
    region_id     integer      NULL REFERENCES regions(id),
    map_id        integer      NULL REFERENCES maps(id),
    slug          varchar(96)  NOT NULL UNIQUE,
    armory_label  varchar(96)  NOT NULL UNIQUE,
    name          varchar(96)  NULL,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);

-- 2 containers. ⚠️ NOT places, which is the whole reason they have their own
-- table: they have no region and no map, and the dungeons that drop them span several.
CREATE TABLE containers (
    id            serial PRIMARY KEY,
    slug          varchar(96)  NOT NULL UNIQUE,
    name          varchar(96)  NOT NULL UNIQUE,
    confidence_id integer       NOT NULL REFERENCES confidence_levels(id),
    source_note   varchar(300) NOT NULL,
    open_question varchar(300) NULL
);

